var dispositivo = JSON.parse(metadata.dispositivo);
var tipoDispositivo = dispositivo.tipoDispositivo;
var umbrales = dispositivo.umbrales;

if(!umbrales){
    var umbralesGlobales = JSON.parse(metadata.umbrales);
    umbrales = (dispositivo.subTipo !== undefined) ?
        umbralesGlobales[dispositivo.dispositivo][tipoDispositivo][dispositivo.subTipo] :
        umbralesGlobales[dispositivo.dispositivo][tipoDispositivo];
}

var v1 = msg.voltaje_1;
var v2 = msg.voltaje_2;
var v3 = msg.voltaje_3;

var voltajesCero = (v1 === 0 && v2 === 0 && v3 === 0);
var frecuenciaCero = (msg.frecuencia === 0);

var alarma = null;
var umbralAlarma = null;
var fueraUmbral = false;
var severity = "normal";

if (voltajesCero) {

    severity = "CRITICAL";

    if (tipoDispositivo === "PLANTA") {
        alarma = "Planta encendida";
        umbralAlarma = "apagado";
    } else if (frecuenciaCero) {
        alarma = "Corte de energía";
        umbralAlarma = "v_corte";
        fueraUmbral = true;
    }
}else{
    // Planta encendida
    if (tipoDispositivo === "PLANTA") {
        alarma = "Planta encendida";
        umbralAlarma = "encendido";
        fueraUmbral = true;
        severity = "CRITICAL";
    }else{
        // Voltaje alto
        if (v1 > umbrales.v_superior || v2 > umbrales.v_superior || v3 > umbrales.v_superior) {
            alarma = "Voltaje alto";
            umbralAlarma = "v_superior";
            fueraUmbral = true;
        }

        // Voltaje bajo
        if (v1 < umbrales.v_inferior || v2 < umbrales.v_inferior || v3 < umbrales.v_inferior) {
            alarma = "Voltaje bajo";
            umbralAlarma = "v_inferior";
            fueraUmbral = true;
        }

        if(fueraUmbral){
            var nivelesAlarma = (dispositivo.umbrales !== undefined) ? dispositivo.umbrales.v_levelsAlarm : umbrales.v_levelsAlarm;

            if(typeof nivelesAlarma === "object"){
                for (var i = 0; i < nivelesAlarma.length; i++) {
                    var nivel = nivelesAlarma[i];
                    if ((v1 > nivel.min && v1 <= nivel.max) ||
                        (v2 > nivel.min && v2 <= nivel.max) ||
                        (v3 > nivel.min && v3 <= nivel.max)) {
                        severity = nivel.level;
                        break;
                    }
                }
            }else{
                severity = nivelesAlarma;
            }
        }
    }
}

dispositivo.umbralAlarma = umbralAlarma;
dispositivo.alarma = alarma;
dispositivo.umbrales = umbrales;
dispositivo.voltaje = {
    voltaje_1: v1,
    voltaje_2: v2,
    voltaje_3: v3
};

metadata.dispositivo = JSON.stringify(dispositivo);
metadata.fueraUmbralVoltaje = fueraUmbral;
metadata.severity = severity;

delete metadata.umbrales;

return {msg: msg, metadata: metadata, msgType: msgType};

