var tipoDispositivo = dispositivo.tipoDispositivo;

var histeresis = dispositivo.histeresis;

if(!histeresis){
    var histeresisGlobal = JSON.parse(metadata.histeresis);
    histeresis = (dispositivo.subTipo !== undefined) ?
        histeresisGlobal[dispositivo.dispositivo][tipoDispositivo][dispositivo.subTipo] :
        histeresisGlobal[dispositivo.dispositivo][tipoDispositivo];
}

var umbralAlarma = dispositivo.umbralAlarma;

var alarma = "";
var newHisteresis = "";
var histeresisClear = "";

//var mensaje = "[" + tipoDispositivo + ((tipoDispositivo === "UPS") ? ((dispositivo.subTipo === "entrada") ? "E" : "S") : "") + "]" + " - " + dispositivo.alarma;

var mensaje = "[" + tipoDispositivo + "]" + " - " + dispositivo.alarma;

var clave = "";
switch (umbralAlarma) {
    case 'v_corte':
        clave = "CE";
        break;
    case 'v_superior':
        clave = "VA";
        break;
    case 'v_inferior':
        clave = "VB";
        break;
    case 'encendido':
        clave = "PE";
        break;
}

var histeresisDispositivo = (msg["histeresis"+clave] === undefined) ? false : msg["histeresis"+clave];

if(!histeresis[umbralAlarma].histeresis){
    alarma = mensaje;
    newHisteresis = metadata.ts;
}else{
    if(histeresisDispositivo !== false){
        var tsObjetivo = sumarTiempo(parseInt(histeresisDispositivo), parseInt(histeresis[umbralAlarma].histeresis.time), histeresis[umbralAlarma].histeresis.unit);

        if(metadata.ts > tsObjetivo){
            alarma = mensaje;
        }
    }else{
        newHisteresis = metadata.ts;
    }

    if(newHisteresis !== false){
        histeresisClear = false;
    }
}

if(newHisteresis !== ""){
    msg.histeresis = newHisteresis;
}

if(histeresisClear !== ""){
    msg.histeresisClear = histeresisClear;
}

msg.nombreAlarma = alarma;
dispositivo.clave = clave;

metadata.dispositivo = JSON.stringify(dispositivo);

delete metadata.histeresis;

return {msg: msg, metadata: metadata, msgType: msgType};

var dispositivo = JSON.parse(metadata.dispositivo);

var fueraUmbral = JSON.parse(metadata.fueraUmbralVoltaje);
if(dispositivo.tipoDispositivo === "PLANTA"){
    fueraUmbral = (fueraUmbral !== false);
    if(dispositivo.umbralAlarma === "encendido"){
        if((msg.alarmaVA !== undefined && msg.alarmaVA !== false) || (msg.alarmaVB !== undefined && msg.alarmaVB !== false)){
            fueraUmbral = false;
        }
    }
}else{
    fueraUmbral = (fueraUmbral !== false);
}

return fueraUmbral;

var dispositivo = JSON.parse(metadata.dispositivo);
var newMSG = {};

if(msg.histeresisClear !== undefined){
    newMSG["histeresisClear"+dispositivo.clave] = (msg.histeresisClear !== false) ? parseInt(msg.histeresisClear) : msg.histeresisClear;
}

if(msg.histeresis !== undefined){
